import {
  array,
  createTypeContext,
  declare,
  docComment,
  object,
  type JsonSchema,
  typeDeclaration,
} from "./render-defs.js";

const header = `// Generated by tooling/generate-types from definitions/openapi.json.
// Do not edit by hand.
`;

const schemaRef = "#/components/schemas/";
const runtimeRef = "runtime.schema.json#/$defs/";
const compositionRef = "composition.schema.json";
const compositionType = "LumenComposition";

/** A union that also takes any other string, because another host can send values of its own. */
function openUnion(name: string, def: JsonSchema, values: readonly unknown[]): string {
  const union = values.map((value) => `  | ${JSON.stringify(value)}`).join("\n");
  return `${docComment(def.description, "")}export type ${name} =\n${union}\n  | (string & {});`;
}

/** \`ErrorCode\` as an open union, and the table of the listed codes with their descriptions. */
function renderErrorCode(name: string, def: JsonSchema): string {
  const codes = array(def["x-lumen-codes"]).map(object);
  if (codes.length === 0) throw new Error(`\`${name}\` lists no codes`);
  return `${openUnion(
    name,
    def,
    codes.map((entry) => entry.code),
  )}

/** Each error code lumen-server sends, with what it means. */
export const errorCodes = [
${codes.map((entry) => `  { code: ${JSON.stringify(entry.code)}, description: ${JSON.stringify(entry.description)} },`).join("\n")}
] as const;`;
}

/** The content type and file extension of each output format. */
function renderOutputFiles(def: JsonSchema): string {
  const files = array(def["x-lumen-files"]).map(object);
  if (files.length === 0) throw new Error("`OutputFormat` lists no files");
  const entries = files
    .map(
      (file) =>
        `  ${JSON.stringify(file.format)}: { contentType: ${JSON.stringify(file.contentType)}, extension: ${JSON.stringify(file.extension)} },`,
    )
    .join("\n");
  return `/** What a render of each output format downloads as: its content type and file extension. */
export const outputFiles = {
${entries}
} as const satisfies Readonly<Record<OutputFormat, { readonly contentType: string; readonly extension: string }>>;`;
}

/** The values a string union lists, from an \`enum\` or a \`oneOf\` of constants. */
function unionValues(def: JsonSchema): readonly unknown[] {
  if (Array.isArray(def.enum)) return def.enum;
  return array(def.oneOf).map((branch) => {
    const value = object(branch).const;
    if (value === undefined) throw new Error(`an open union has a branch that is not a constant`);
    return value;
  });
}

const methods = ["get", "post", "put", "delete"] as const;

/** What an operation's request or answer carries, and the name of its type when that is JSON. */
function bodyOf(content: unknown): { readonly kind: string; readonly type: string } {
  if (content === undefined) return { kind: "none", type: "undefined" };
  const json = object(content)["application/json"];
  if (json === undefined) return { kind: "bytes", type: "ArrayBuffer" };
  const ref = object(object(json).schema).$ref;
  if (typeof ref !== "string" || !ref.startsWith(schemaRef)) {
    throw new Error("a JSON body is not a reference to a schema");
  }
  return { kind: "json", type: ref.slice(schemaRef.length) };
}

/** The table of operations and the types each takes and answers with. */
function renderOperations(document: JsonSchema): string {
  const entries: string[] = [];
  const types: string[] = [];
  for (const [path, item] of Object.entries(object(document.paths))) {
    for (const method of methods) {
      const operation = object(item)[method];
      if (operation === undefined) continue;
      const { operationId, requestBody, responses, summary } = object(operation);
      if (typeof operationId !== "string") throw new Error(`${method} ${path} has no operationId`);
      const request = bodyOf(requestBody === undefined ? undefined : object(requestBody).content);
      const socket = object(operation)["x-lumen-socket"];
      const success = Object.entries(object(responses)).filter(([status]) => status < "300");
      const answers = success.map(([, response]) => bodyOf(object(response).content));
      const response =
        socket !== undefined
          ? {
              kind: "socket",
              type: bodyOf({ "application/json": { schema: object(socket).message } }).type,
            }
          : answers[0];
      if (response === undefined || answers.some((answer) => answer.type !== answers[0]?.type)) {
        throw new Error(`\`${operationId}\` has no one type of success`);
      }
      entries.push(
        `${docComment(typeof summary === "string" ? summary : undefined, "  ")}  ${operationId}: { method: ${JSON.stringify(method.toUpperCase())}, path: ${JSON.stringify(path)}, request: ${JSON.stringify(request.kind)}, response: ${JSON.stringify(response.kind)} },`,
      );
      types.push(
        `  readonly ${operationId}: { readonly request: ${request.type}; readonly response: ${response.type} };`,
      );
    }
  }
  if (entries.length === 0) throw new Error("the OpenAPI document has no operations");
  return `/** The version of the API these types describe: the OpenAPI document's \`info.version\`. */
export const apiVersion = ${JSON.stringify(object(document.info).version)};

/**
 * Every route of the API: its method, its path with each parameter as \`{name}\`, and whether its
 * request and its answer are JSON, raw bytes or nothing. A \`socket\` answer is a WebSocket.
 */
export const apiOperations = {
${entries.join("\n")}
} as const;

export type ApiOperationId = keyof typeof apiOperations;

/**
 * What each operation takes and answers with on success. Raw bytes are \`ArrayBuffer\`, and a
 * socket's type is the type of its messages.
 */
export interface ApiOperationTypes {
${types.join("\n")}
}`;
}

/**
 * The contents of `generated/api.ts`: the types and routes of lumen-server's HTTP API. Values the
 * engine produces are the runtime types, and a request's composition is \`LumenComposition\`.
 */
export function renderApiTypes(document: JsonSchema, runtimeSchema: JsonSchema): string {
  const defs = object(object(document.components).schemas) as Record<string, JsonSchema>;
  const runtimeNames = Object.keys(object(runtimeSchema.$defs));
  const context = createTypeContext(
    defs,
    [
      ...Object.keys(defs).map((name): [string, string] => [`${schemaRef}${name}`, name]),
      ...runtimeNames.map((name): [string, string] => [`${runtimeRef}${name}`, name]),
      [compositionRef, compositionType],
    ],
    true,
  );
  const constants: string[] = [];
  for (const [name, def] of Object.entries(defs)) {
    if (def["x-lumen-codes"] !== undefined) {
      declare(context, name, renderErrorCode(name, def));
    } else if (def["x-lumen-open"] === true) {
      declare(context, name, openUnion(name, def, unionValues(def)));
    } else {
      declare(context, name, typeDeclaration(name, def, context, true));
    }
    if (def["x-lumen-files"] !== undefined) constants.push(renderOutputFiles(def));
  }

  const runtimeImports = runtimeNames.filter((name) => context.used.has(name)).sort();
  const imports = [
    ...(context.used.has(compositionType)
      ? [`import type { ${compositionType} } from "./schema.js";`]
      : []),
    ...(runtimeImports.length > 0
      ? [`import type { ${runtimeImports.join(", ")} } from "./runtime.js";`]
      : []),
  ];
  return `${header}
${imports.join("\n")}

${[...context.declarations.values(), ...constants, renderOperations(document)].join("\n\n")}
`;
}
